import math

def P1(x):
    """Calculates P1(x) = x^3 - 12295798x + 16583737313"""
    return x**3 - 12295798*x + 16583737313

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    root = int(math.isqrt(n))
    return root * root == n

print("--- Testing n in [-10, 10] ---")
results_small_n = {}
for n in range(-10, 11):
    if n == 2024 or n == 2025: # Should not happen in this range, but good practice
        continue

    Pn = P1(n)
    is_sq = is_perfect_square(Pn)

    # Check P(2024) and P(2025) just to be sure the setup is correct for n=2024, 2025
    if n == 2024:
        print(f"P1(2024) = {P1(2024)}. Is square: {is_perfect_square(P1(2024))}")
    elif n == 2025:
        print(f"P1(2025) = {P1(2025)}. Is square: {is_perfect_square(P1(2025))}")

    results_small_n[n] = {
        'Pn': Pn,
        'is_square': is_sq
    }

    status = "Square" if is_sq else "Not Square"
    print(f"n={n}: P1({n}) = {Pn}, is a square: {is_sq} ({status})")

print("\n--- Summary for small n ---")
non_square_count = sum(1 for n in results_small_n if not results_small_n[n]['is_square'])
print(f"Out of 21 values tested (excluding 2024, 2025), {non_square_count} are not squares.")
